/**
 * Shared helper for the PostgreSQL-backed verification scripts.
 *
 * Loads the test-only Prisma Client generated by `prepare-test-prisma-client.ts`
 * (query compiler + `pg` driver adapter, no native engine binary) and exposes it
 * in a shape that `PrismaDataRepository` accepts, so the production repository
 * code runs unmodified against a real database.
 */
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { fileURLToPath } from 'node:url';
import { PrismaPg } from '@prisma/adapter-pg';
import type { PrismaClient } from '@prisma/client';

const scriptDirectory = path.dirname(fileURLToPath(import.meta.url));
const apiRoot = path.resolve(scriptDirectory, '..');
const clientEntry = path.join(apiRoot, '.prisma-test-client', 'client', 'index.js');
const hashFile = path.join(apiRoot, '.prisma-test-client', 'schema.sha256');
const sourceSchema = path.join(apiRoot, 'prisma', 'schema.prisma');

export interface DisconnectablePrismaClient extends PrismaClient {
  $disconnect(): Promise<void>;
}

export async function createPostgresTestClient(databaseUrl: string): Promise<{
  prisma: DisconnectablePrismaClient;
  adapter: PrismaPg;
}> {
  if (!existsSync(clientEntry)) {
    throw new Error(
      `The PostgreSQL test Prisma Client is missing (${path.relative(apiRoot, clientEntry)}). ` +
        'Run `npm run db:test-client -w @orqeli/api` first.'
    );
  }

  // Refuse to verify against a client generated from an older schema: a stale
  // client would silently test the wrong model definitions.
  const expectedHash = createHash('sha256').update(readFileSync(sourceSchema, 'utf8')).digest('hex');
  const recordedHash = existsSync(hashFile) ? readFileSync(hashFile, 'utf8').trim() : '';
  if (recordedHash !== expectedHash) {
    throw new Error(
      'The PostgreSQL test Prisma Client is stale relative to prisma/schema.prisma. ' +
        'Re-run `npm run db:test-client -w @orqeli/api`.'
    );
  }

  const generated = (await import(pathToFileURL(clientEntry).href)) as {
    PrismaClient: new (options: { adapter: PrismaPg }) => unknown;
  };
  const adapter = new PrismaPg({ connectionString: databaseUrl });
  const client = new generated.PrismaClient({ adapter });

  return {
    prisma: client as unknown as DisconnectablePrismaClient,
    adapter
  };
}
